/* --- teamexpand --- */
document.addEventListener("DOMContentLoaded",function(){var g=document.querySelector(".team_grid");if(!g)return;var b=document.createElement("button");b.type="button";b.className="team_expand-btn";b.textContent="Ver mais da equipe";function sync(){var mobile=window.innerWidth<600;b.style.display=mobile?"flex":"none";if(!mobile){g.classList.remove("is-expanded");b.textContent="Ver mais da equipe"}}sync();g.parentNode.insertBefore(b,g.nextSibling);b.addEventListener("click",function(){g.classList.toggle("is-expanded");b.textContent=g.classList.contains("is-expanded")?"Ver menos da equipe":"Ver mais da equipe"});window.addEventListener("resize",sync)});

/* --- teamdetails --- */
(function(){var MORE="Ver mais detalhes",LESS="Ver menos detalhes";function init(){document.querySelectorAll(".team_card").forEach(function(card){card.querySelectorAll(".team_more-btn").forEach(function(b){b.remove()});var det=card.querySelector(".team_details");if(!det)return;det.hidden=false;det.removeAttribute("hidden");var btn=card.querySelector(".card-details__button");if(!btn)return;var lis=det.querySelectorAll("li");if(lis.length<=2&&det.textContent.trim().length<140){btn.hidden=true;var w=btn.closest(".card-details__button__wrapper");if(w)w.style.display="none";card.querySelectorAll(".team_details__fade").forEach(function(f){f.style.display="none"});return}card.classList.add("has-details-toggle");var host=card.querySelector(".team_card-body-details")||det.parentElement;var fade=det.querySelector(".team_details__fade")||(host&&host.querySelector(".team_details__fade"))||card.querySelector(".team_details__fade");if(!fade){fade=document.createElement("div");fade.className="team_details__fade";fade.setAttribute("aria-hidden","true")}if(fade.parentElement!==det)det.appendChild(fade);btn.hidden=false;btn.removeAttribute("hidden");btn.style.removeProperty("display");var bw=btn.closest(".card-details__button__wrapper");if(bw)bw.style.removeProperty("display");if(!btn.dataset.moreLabel)btn.dataset.moreLabel=(btn.textContent||MORE).trim()||MORE;if(!card.classList.contains("is-details-open")){btn.textContent=btn.dataset.moreLabel;btn.setAttribute("aria-expanded","false")}if(btn.dataset.bound)return;btn.dataset.bound="1";btn.addEventListener("click",function(e){e.preventDefault();var open=card.classList.toggle("is-details-open");btn.setAttribute("aria-expanded",open?"true":"false");btn.textContent=open?LESS:btn.dataset.moreLabel})})}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init);else init()})();

/* --- ovulusswipers --- */
(function(){var IDS={testimonials:{id:"testimonials-swiper",mobileOnly:false,autoplay:true},blog:{id:"blog-swiper",mobileOnly:true},media:{id:"media-swiper",mobileOnly:true}};var mq=window.matchMedia("(max-width:767px)");function conf(o){var c={slidesPerView:"auto",spaceBetween:20,grabCursor:true,simulateTouch:true,allowTouchMove:true,watchOverflow:true,speed:450,resistanceRatio:.65,pagination:{el:"#"+o.id+" .swiper-pagination",clickable:true},breakpoints:{0:{spaceBetween:14},768:{spaceBetween:18},1024:{spaceBetween:22}}};if(o.autoplay)c.autoplay={delay:5000,disableOnInteraction:false,pauseOnMouseEnter:true};return c}function mount(o){var el=document.getElementById(o.id);if(!el)return;if(el.swiper){el.swiper.destroy(true,true)}if(o.mobileOnly&&!mq.matches)return;try{new Swiper("#"+o.id,conf(o))}catch(e){}}function all(){Object.keys(IDS).forEach(function(k){mount(IDS[k])})}function wait(){var n=0;(function loop(){n++;if(typeof Swiper==="undefined"){if(n<40)return setTimeout(loop,120);return}all();if(mq.addEventListener)mq.addEventListener("change",all);else mq.addListener(all)})()}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",wait);else wait()})();
